sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {

        if (!gs.nil(current.folio_number)) { // && !sysIdRegex.test(current.customer_name)) {
            var cn = new GlideRecord('x_ssad6_paquetiz_0_ord_servicio');
            cn.addQuery('folio_number', current.folio_number);
            cn.query();
            if (cn.next()) {
                current.folio_number = null;
            } else {
                current.assignment_group = "14c889db47a0be106c0c59f4f16d43f7"; //Logística paquetizados
                if (current.service_acronym == 7) { //Si es servicio especial(SSE-) se marca true
                    current.special_packaged = true;
                } else {
                    current.special_packaged = false;
                }
                var emailRegex = /^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/;
                if (!gs.nil(current.cap_email) && !emailRegex.test(current.cap_email)) {
                    current.cap_email = null;
                    current.setAbortAction(true);
                }
                //var sysIdRegex = /^[0-9a-f]{32}$/; // patrón sys_id para validar si ya esta referenciado
                if (!gs.nil(current.company_name)) { // && !sysIdRegex.test(current.customer_name)) {
                    var cn = new GlideRecord('customer_account');
                    cn.addQuery('name', 'CONTAINS', current.company_name);
                    cn.query();
                    if (cn.next()) {
                        current.customer_name = cn.getUniqueValue();
                    }
                }
            }
        }

    } catch (error) {
        gs.error('Error al validar campos de OS ' + current.number + ", error: " + error);
    }
})(current, previous);
